import 'package:freezed_annotation/freezed_annotation.dart';

part 'surah_header_glyph_models.freezed.dart';

/// One Surah's verified decorative header glyph, generated by
/// `tool/quran_data/src/surah_header_font_package.dart` from QUL's own
/// official ligature/JSON mapping cross-checked against the real font's
/// `cmap` table — never hand-written or guessed. [inputText] is the exact
/// string to hand a [TextPainter]/`Text` widget styled with [fontFamily];
/// it is QUL's own mapped codepoint (verified present in the font, not
/// assumed), never a value this codebase invents.
@freezed
abstract class SurahHeaderGlyphEntry with _$SurahHeaderGlyphEntry {
  const factory SurahHeaderGlyphEntry({
    required int surahNumber,

    /// The exact input string (one Unicode codepoint, per QUL's own
    /// ligature JSON) that renders this Surah's complete decorative header
    /// glyph in [fontFamily] — never the surah's plain name.
    required String inputText,
    required String fontFamily,
  }) = _SurahHeaderGlyphEntry;
}

/// The full 114-surah decorative-header glyph mapping for one font, plus
/// enough provenance to know exactly which upstream font and ligature
/// mapping it was verified against.
@freezed
abstract class SurahHeaderGlyphManifest with _$SurahHeaderGlyphManifest {
  const factory SurahHeaderGlyphManifest({
    required int schemaVersion,

    /// Path Flutter's `rootBundle` resolves the font file at.
    required String assetPath,
    required String fontFamily,
    required String fontSource,
    required String fontHash,
    required String ligatureMappingSource,
    required String ligatureMappingHash,
    required DateTime generatedAt,
    required List<SurahHeaderGlyphEntry> entries,
  }) = _SurahHeaderGlyphManifest;
}
